--- 初始化玩家信息
function LadderStruggleMainRankCard:InitPlayerInfo()
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    ---@type PlayerDojo
    local playerDojo = playerComponent:GetPlayerDojo()
    self.Txt_PlayerName.text = playerDojo.playerName
    self.Txt_PlayerLevel.text = tostring(playerDojo.level)
    

    local LT_PlayerHead = self.LB_PlayerHead.Env
    if IsNull(LT_PlayerHead) then
        self.LB_PlayerHead:Init()
        LT_PlayerHead = self.LB_PlayerHead.Env
    end
    local avatarId = checkInt(playerDojo.playerAvatar)
    local avatarFrameId = checkInt(playerDojo.playerAvatarFrame)
    LT_PlayerHead:FreshAvatarFrame(avatarId, avatarFrameId)
end

