--- 领奖按钮回调
---@param state any
function LadderStruggleMainRankCard:OnGetReward(state)
    if state == BtnGetRewardState.Lock then
        GameUtils.Toast(CantGetTips)
    elseif state == BtnGetRewardState.Active then
        -- 领取奖励
        GameUtils.CommonDrawRewards(self.component.InterfaceRankReward, nil, {{id = self.component.UIMainDialog}})
    elseif state == BtnGetRewardState.Complete then
        GameUtils.Toast(HasGetTips)
    end
end

--- 设置玩家rank信息
---@param data any
function LadderStruggleMainRankCard:SetPlayerRankInfo(rank, rankPercentage)
    if rank == 0 then
        KTool.SetActive(self.Txt_PlayerRank, false)
        KTool.SetActive(self.RT_NoneRank, true)
    else
        KTool.SetActive(self.Txt_PlayerRank, true)
        KTool.SetActive(self.RT_NoneRank, false)
        self.Txt_PlayerRank.text = tostring(rank)
    end
    self.myRank = rank
    if rankPercentage then
        self.myRankPercentage = rankPercentage
    end
end

--- 设置玩家战力
---@param value any
function LadderStruggleMainRankCard:SetPlayerCombatValue(value)
    self.Txt_PlayerCombatValue.text = tostring(value)
end

--- 设置所属系统
function LadderStruggleMainRankCard:SetSystem(systemName)
    self.systemName = systemName
    self.component = GameUtils.GetECSComponentBySystemName(systemName)
end

--- 设置赛季结束时间
---@param second any
function LadderStruggleMainRankCard:SetSeasonEndTime(second)
    CfUtils.FillText(self.controller.transform:Find("CutTimeNode/TxtTime"), CfUtils.GetTimeHMS4(second))
end

--- 玩家排名变化的动画
function LadderStruggleMainRankCard:PlayerRankChangeAnimation()
    KTool.SetActive(self.RT_RankChangeFX, false)
    KTool.SetActive(self.RT_RankChangeFX, true)
end

